WITH cleaned AS (SELECT id, session_id, event_type, page, event_time, duration_sec, CASE WHEN event_type IN ('add_to_cart', 'purchase') THEN 'Tier 1' ELSE 'Other' END event_type_group, COALESCE(page, 'OTHER') page_clean FROM web_events WHERE event_type <> 'page_view'), enriched AS (SELECT s.id, s.session_id, s.page, s.event_time, s.page_clean, p2.browser, p2.device FROM cleaned s LEFT JOIN sessions p2 ON s.session_id = p2.id), enriched_web_events AS (SELECT src.id, src.session_id, src.page, b.country, b.device AS session_device FROM enriched src INNER JOIN sessions b ON src.session_id = b.id), with_dims AS (SELECT a.*, p.country AS session_country FROM enriched_web_events a INNER JOIN sessions p ON a.session_id = p.id), enriched_web_events_2 AS (SELECT s.id, s.session_id, s.session_country, p2.country AS session_country_2 FROM with_dims s INNER JOIN sessions p2 ON s.session_id = p2.id WHERE p2.country = 'DE') SELECT session_id, COUNT(CASE WHEN session_country_2 = 'SG' THEN 1 END) AS sg_count, COUNT(CASE WHEN session_country = 'US' THEN 1 END) AS us_count FROM enriched_web_events_2 GROUP BY ROLLUP (session_id)
